$ErrorActionPreference = "Stop"

$root = Split-Path -Parent $PSScriptRoot
$utf8 = New-Object System.Text.UTF8Encoding($false)

function Decode([string]$Value) {
    return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}

$block = Decode ""

$financePath = Join-Path $root "app\api\provider\finance\route.ts"
$auditPath = Join-Path $root "app\api\provider\finance-audit\route.ts"
$pagePath = Join-Path $root "app\provider\payments\page.tsx"

foreach ($path in @($financePath, $auditPath, $pagePath)) {
    if (-not (Test-Path -LiteralPath $path)) {
        throw "13.11 : fichier requis introuvable : $path"
    }
}

$finance = [System.IO.File]::ReadAllText($financePath)
$audit = [System.IO.File]::ReadAllText($auditPath)
$page = [System.IO.File]::ReadAllText($pagePath)

if (-not $finance.Contains("KLYX_GROUP_SCHEMA_RUNTIME_FINANCE_13_05C")) {
    throw "13.11 : KLYX 13.05c introuvable."
}

if (-not $audit.Contains("KLYX_GROUP_FINANCE_AUDIT_API_13_03")) {
    throw "13.11 : audit financier 13.03 introuvable."
}

if (-not $page.Contains("KLYX_GROUP_FINANCE_AUDIT_PAGE_13_03")) {
    throw "13.11 : page paiements 13.03 introuvable."
}

if ($finance.Contains("KLYX_CANONICAL_FINANCE_TRANSACTIONS_13_11")) {
    Write-Host "KLYX 13.11 deja applique."
    exit 0
}

# ------------------------------------------------------------
# 1. Renomme uniquement la liste ledger brute.
# ------------------------------------------------------------

$pattern = '(?m)^\s{4}const transactions\s*='
$matches = [regex]::Matches($finance, $pattern)

if ($matches.Count -ne 1) {
    throw "13.11 : declaration transactions ambigue. Nombre trouve : $($matches.Count)"
}

$match = $matches[0]

$replacement = "    const rawTransactions13_11 ="

$finance =
    $finance.Remove(
        $match.Index,
        $match.Length
    ).Insert(
        $match.Index,
        $replacement
    )

# ------------------------------------------------------------
# 2. Insere la canonicalisation juste avant le retour final.
# ------------------------------------------------------------

$anchor = "    return NextResponse.json({"
$returnIndex = $finance.LastIndexOf($anchor)

if ($returnIndex -lt 0) {
    throw "13.11 : retour final finance introuvable."
}

$finance =
    $finance.Insert(
        $returnIndex,
        $block + "`r`n`r`n"
    )

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"

Copy-Item -LiteralPath $financePath -Destination ($financePath + ".bak-13-11-" + $timestamp) -Force

[System.IO.File]::WriteAllText($financePath, $finance, $utf8)

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 13.11 APPLIQUE"
Write-Host "======================================"
Write-Host "Transactions simples : 1 LIGNE LEDGER"
Write-Host "Mission groupee : 1 EVENEMENT COMMERCIAL"
Write-Host "Allocations enfants UI : FUSIONNEES"
Write-Host "Montant groupe : CANONIQUE"
Write-Host "Ledger DB : INCHANGE"
Write-Host "Audit 13.03 : INCHANGE"
Write-Host "Stripe : INCHANGE"
Write-Host "Migration : AUCUNE"
Write-Host "======================================"
